use std::fmt::Write;

use riscv_asm_lsp::data::RiscvData;

use crate::join::JoinReportData;
use crate::pins;

pub fn render(data: &RiscvData, report: &JoinReportData) -> String {
    let mut out = String::new();
    render_header(&mut out);
    render_summary(&mut out, data, report);
    render_lists(&mut out, report);
    out
}

fn render_header(out: &mut String) {
    let _ = writeln!(
        out,
        "<!-- Generated by cargo xtask gen-data. Do not edit by hand. -->"
    );
    let _ = writeln!(out);
    let _ = writeln!(out, "# Data Generation Report");
    let _ = writeln!(out);
    let _ = writeln!(out, "## Pinned Inputs");
    let _ = writeln!(out);
    let _ = writeln!(out, "| Input | Version |");
    let _ = writeln!(out, "| --- | --- |");
    let _ = writeln!(out, "| LLVM | `{}` |", pins::LLVM_TAG);
    let _ = writeln!(out, "| riscv-unified-db | `{}` |", pins::UDB_COMMIT);
    let _ = writeln!(out, "| riscv-asm-manual | `{}` |", pins::ASM_MANUAL_COMMIT);
    let _ = writeln!(out);
}

fn render_summary(out: &mut String, data: &RiscvData, report: &JoinReportData) {
    let llvm_inst_count = data
        .instructions
        .iter()
        .filter(|i| i.llvm_supported)
        .count();
    let doc_only_inst_count = data
        .instructions
        .iter()
        .filter(|i| !i.llvm_supported)
        .count();
    let llvm_only_total = report.llvm_only_with_manual.len()
        + report.llvm_only_with_supplement.len()
        + report.llvm_only_no_desc.len();
    let llvm_csr_count = data.csrs.iter().filter(|c| c.llvm_supported).count();
    let doc_only_csr_count = data.csrs.iter().filter(|c| !c.llvm_supported).count();

    let llvm_major = pins::LLVM_TAG
        .strip_prefix("llvmorg-")
        .unwrap_or(pins::LLVM_TAG)
        .split('.')
        .next()
        .filter(|s| !s.is_empty())
        .unwrap_or("LLVM");

    let _ = writeln!(out, "## Summary");
    let _ = writeln!(out);
    let _ = writeln!(out, "| Metric | Count |");
    let _ = writeln!(out, "| --- | ---: |");
    let _ = writeln!(out, "| Extensions | {} |", data.extensions.len());
    let _ = writeln!(
        out,
        "| Instructions & aliases (LLVM supported; `.insn_*` excluded) | {} |",
        llvm_inst_count
    );
    let _ = writeln!(
        out,
        "| Instructions in both LLVM and riscv-unified-db | {} |",
        report.both_instructions
    );
    let _ = writeln!(
        out,
        "| Instructions only in LLVM vs riscv-unified-db (total) | {} |",
        llvm_only_total
    );
    let _ = writeln!(
        out,
        "| In LLVM, described by riscv-asm-manual | {} |",
        report.llvm_only_with_manual.len()
    );
    let _ = writeln!(
        out,
        "| In LLVM, described by project supplements | {} |",
        report.llvm_only_with_supplement.len()
    );
    let _ = writeln!(
        out,
        "| In LLVM, no description | {} |",
        report.llvm_only_no_desc.len()
    );
    let _ = writeln!(
        out,
        "| Only in riscv-unified-db (not accepted by LLVM {llvm_major}) | {} |",
        doc_only_inst_count
    );
    let _ = writeln!(
        out,
        "| rv64gc instructions in riscv-unified-db missing from LLVM | {} |",
        report.missing_rv64gc.len()
    );
    let _ = writeln!(out, "| CSRs (LLVM supported) | {} |", llvm_csr_count);
    let _ = writeln!(
        out,
        "| CSRs in both LLVM and riscv-unified-db | {} |",
        report.both_csrs
    );
    let _ = writeln!(
        out,
        "| CSRs only in LLVM, described by project supplements | {} |",
        report.llvm_only_csrs_with_supplement.len()
    );
    let _ = writeln!(
        out,
        "| CSRs only in LLVM (no description) | {} |",
        report.llvm_only_csrs.len()
    );
    let _ = writeln!(
        out,
        "| CSRs only in riscv-unified-db (not accepted by LLVM {llvm_major}) | {} |",
        doc_only_csr_count
    );
    let _ = writeln!(out, "| Registers | {} |", data.registers.len());
    let _ = writeln!(out, "| Directives | {} |", data.directives.len());
    let _ = writeln!(
        out,
        "| Cleaned TODOs from riscv-unified-db | {} |",
        report.cleaned_todos.len()
    );
    let _ = writeln!(out);
}

fn write_name_section(out: &mut String, title: &str, items: &[String]) {
    let _ = writeln!(out, "## {title} ({})", items.len());
    let _ = writeln!(out);
    for m in items {
        let _ = writeln!(out, "- `{m}`");
    }
    let _ = writeln!(out);
}

fn write_csr_section(out: &mut String, title: &str, items: &[(String, u16)]) {
    let _ = writeln!(out, "## {title} ({})", items.len());
    let _ = writeln!(out);
    for (name, num) in items {
        let _ = writeln!(out, "- `{name}` (`0x{num:03x}`)");
    }
    let _ = writeln!(out);
}

fn render_lists(out: &mut String, report: &JoinReportData) {
    if !report.missing_rv64gc.is_empty() {
        let _ = writeln!(out, "## rv64gc Instructions Missing from LLVM");
        let _ = writeln!(out);
        for m in &report.missing_rv64gc {
            let _ = writeln!(out, "- `{m}`");
        }
        let _ = writeln!(out);
    }

    write_name_section(
        out,
        "In LLVM, Described by riscv-asm-manual",
        &report.llvm_only_with_manual,
    );
    write_name_section(
        out,
        "In LLVM, Described by Project Supplements",
        &report.llvm_only_with_supplement,
    );
    write_name_section(out, "In LLVM, No Description", &report.llvm_only_no_desc);
    write_name_section(
        out,
        "Only in riscv-unified-db",
        &report.udb_only_instructions,
    );

    write_csr_section(
        out,
        "CSRs Only in LLVM, Described by Project Supplements",
        &report.llvm_only_csrs_with_supplement,
    );
    write_csr_section(
        out,
        "CSRs Only in LLVM, No Description",
        &report.llvm_only_csrs,
    );
    write_csr_section(out, "CSRs Only in riscv-unified-db", &report.udb_only_csrs);

    if !report.description_corrections.is_empty() {
        let _ = writeln!(
            out,
            "## Description Corrections ({})",
            report.description_corrections.len()
        );
        let _ = writeln!(out);
        for (owner, wrong, right) in &report.description_corrections {
            let _ = writeln!(out, "- `{owner}`: `{wrong}` -> `{right}`");
        }
        let _ = writeln!(out);
    }

    if !report.cleaned_todos.is_empty() {
        write_name_section(
            out,
            "Cleaned TODOs from riscv-unified-db",
            &report.cleaned_todos,
        );
    }

    if !report.udb_copyrights.is_empty() {
        let _ = writeln!(
            out,
            "## riscv-unified-db Copyright Holders ({})",
            report.udb_copyrights.len()
        );
        let _ = writeln!(out);
        for holder in &report.udb_copyrights {
            let _ = writeln!(out, "- {holder}");
        }
        let _ = writeln!(out);
    }

    if !report.deprecated_joined.is_empty() {
        let _ = writeln!(out, "## CSRs Joined via Deprecated Name");
        let _ = writeln!(out);
        for (llvm_name, old_name) in &report.deprecated_joined {
            let _ = writeln!(out, "- `{llvm_name}` <- `{old_name}`");
        }
    }
}
